// Rotate through services based on day of year
const services = [
  {name: 'telemetry-api', path: 'guardspine/telemetry-api/app.py', focus: 'SQL injection defense, connection pooling, error handling'},
  {name: 'soak-monitor', path: 'guardspine/soak-monitor/health-check.sh', focus: 'service coverage, timeout handling, health data storage'},
  {name: 'decision-engine', path: 'guardspine/decision-engine/router.py', focus: 'solver stubs, error handling, dependency checks'},
  {name: 'mirofish-sim', path: 'guardspine/mirofish-sim/app.py', focus: 'resource limits, job cleanup, error handling'},
  {name: 'n8n-pipeline-plugin', path: 'guardspine/extensions/n8n-pipeline/plugin.js', focus: 'error handling, API patterns, security'},
  {name: 'guardspine-plugin', path: 'guardspine/extensions/guardspine/plugin.js', focus: 'L4 approvals, council logic, security'},
  {name: 'litellm-config', path: 'guardspine/litellm/config.yaml', focus: 'model routing, fallback chains, cost optimization'},
  {name: 'agents-shared-context', path: 'guardspine/agents/SHARED-CONTEXT.md', focus: 'agent instructions clarity, accuracy, completeness'},
  {name: 'cmo-prompt', path: 'guardspine/agents/cmo-system-prompt.md', focus: 'outreach quality, PMC decomposition, voice rules'},
  {name: 'content-prompt', path: 'guardspine/agents/content-system-prompt.md', focus: 'content quality, LinkedIn patterns, hook effectiveness'},
  {name: 'cmo-outreach-workflow', path: 'guardspine/n8n-workflows/definitions/cmo-outreach-pipeline.json', focus: 'node connections, error handling, Paperclip auth'},
  {name: 'w3-health-workflow', path: 'guardspine/n8n-workflows/definitions/w3-health-dashboard.json', focus: 'query patterns, threshold logic, alert quality'},
  {name: 'dockerfiles', path: 'guardspine/telemetry-api/Dockerfile', focus: 'security (non-root user, pinned versions), build efficiency'}
];

const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / (24 * 60 * 60 * 1000));
const index = dayOfYear % services.length;
const tonight = services[index];

return [{json: {
  service: tonight.name,
  file_path: tonight.path,
  review_focus: tonight.focus,
  cycle_day: index + 1,
  cycle_total: services.length
}}];
